css:
/* 横組み・吹き出し */
.line{display:inline-block; background:#fffdf5; border:1px solid #d8b56a; border-radius:16px; padding:10px 22px; box-shadow:4px 4px 0 #f0e6cf}
.line+.line{margin-left:14px; margin-top:10px}
/* 縦組み・柱 */
.bands{display:flex; flex-direction:row-reverse; gap:10px; align-items:flex-start}
.band{writing-mode:vertical-rl; text-orientation:upright; background:#2f9b52; color:#fff; border-radius:8px; padding:20px 10px; font-size:26px}
.bands .band:nth-child(2){margin-top:28px}
.bands .band:nth-child(3){margin-top:56px}
